   403  /*
   404   * Variant of decompress_data for use when doing block smoothing.
   405   */
   406
   407  METHODDEF(int)
   408  decompress_smooth_data(j_decompress_ptr cinfo, JSAMPIMAGE output_buf)
   409  {
   410    my_coef_ptr coef = (my_coef_ptr)cinfo->coef;
   411    JDIMENSION last_iMCU_row = cinfo->total_iMCU_rows - 1;
   412    JDIMENSION block_num, last_block_column;
   413    int ci, block_row, block_rows, access_rows;
   414    JBLOCKARRAY buffer;
   415    JBLOCKROW buffer_ptr, prev_block_row, next_block_row;
   416    JSAMPARRAY output_ptr;
   417    JDIMENSION output_col;
   418    jpeg_component_info *compptr;
   419    inverse_DCT_method_ptr inverse_DCT;
   420    boolean first_row, last_row;
   421    JCOEF *workspace;
   422    int *coef_bits;
   423    JQUANT_TBL *quanttbl;
   424    JLONG Q00, Q01, Q02, Q10, Q11, Q20, num;
   425    int DC1, DC2, DC3, DC4, DC5, DC6, DC7, DC8, DC9;
   426    int Al, pred;
   427
   428    /* Keep a local variable to avoid looking it up more than once */
   429    workspace = coef->workspace;
   430
   431    /* Force some input to be done if we are getting ahead of the input. */
   432    while (cinfo->input_scan_number <= cinfo->output_scan_number &&
   433           !cinfo->inputctl->eoi_reached) {
   434      if (cinfo->input_scan_number == cinfo->output_scan_number) {
   435        /* If input is working on current scan, we ordinarily want it to
   436         * have completed the current row.  But if input scan is DC,
   437         * we want it to keep one row ahead so that next block row's DC
   438         * values are up to date.
   439         */
   440        JDIMENSION delta = (cinfo->Ss == 0) ? 1 : 0;
   441        if (cinfo->input_iMCU_row > cinfo->output_iMCU_row + delta)
   442          break;
   443      }
   444      if ((*cinfo->inputctl->consume_input) (cinfo) == JPEG_SUSPENDED)
   445        return JPEG_SUSPENDED;
   446    }
   447
   448    /* OK, output from the virtual arrays. */
   449    for (ci = 0, compptr = cinfo->comp_info; ci < cinfo->num_components;
   450         ci++, compptr++) {
   451      /* Don't bother to IDCT an uninteresting component. */
   452      if (!compptr->component_needed)
   453        continue;
   454      /* Count non-dummy DCT block rows in this iMCU row. */
   455      if (cinfo->output_iMCU_row < last_iMCU_row) {
   456        block_rows = compptr->v_samp_factor;
   457        access_rows = block_rows * 2; /* this and next iMCU row */
   458        last_row = FALSE;
   459      } else {
   460        /* NB: can't use last_row_height here; it is input-side-dependent! */
   461        block_rows = (int)(compptr->height_in_blocks % compptr->v_samp_factor);
   462        if (block_rows == 0) block_rows = compptr->v_samp_factor;
   463        access_rows = block_rows; /* this iMCU row only */
   464        last_row = TRUE;
   465      }
   466      /* Align the virtual buffer for this component. */
   467      if (cinfo->output_iMCU_row > 0) {
   468        access_rows += compptr->v_samp_factor; /* prior iMCU row too */
   469        buffer = (*cinfo->mem->access_virt_barray)
   470          ((j_common_ptr)cinfo, coef->whole_image[ci],
   471           (cinfo->output_iMCU_row - 1) * compptr->v_samp_factor,
   472           (JDIMENSION)access_rows, FALSE);
   473        buffer += compptr->v_samp_factor; /* point to current iMCU row */
   474        first_row = FALSE;
   475      } else {
   476        buffer = (*cinfo->mem->access_virt_barray)
   477          ((j_common_ptr)cinfo, coef->whole_image[ci],
   478           (JDIMENSION)0, (JDIMENSION)access_rows, FALSE);
   479        first_row = TRUE;
   480      }
   481      /* Fetch component-dependent info */
   482      coef_bits = coef->coef_bits_latch + (ci * SAVED_COEFS);
   483      quanttbl = compptr->quant_table;
   484      Q00 = quanttbl->quantval[0];
   485      Q01 = quanttbl->quantval[Q01_POS];
   486      Q10 = quanttbl->quantval[Q10_POS];
   487      Q20 = quanttbl->quantval[Q20_POS];
   488      Q11 = quanttbl->quantval[Q11_POS];
   489      Q02 = quanttbl->quantval[Q02_POS];
   490      inverse_DCT = cinfo->idct->inverse_DCT[ci];
   491      output_ptr = output_buf[ci];
   492      /* Loop over all DCT blocks to be processed. */
   493      for (block_row = 0; block_row < block_rows; block_row++) {
   494        buffer_ptr = buffer[block_row] + cinfo->master->first_MCU_col[ci];
   495        if (first_row && block_row == 0)
   496          prev_block_row = buffer_ptr;
   497        else
   498          prev_block_row = buffer[block_row - 1] +
   499                           cinfo->master->first_MCU_col[ci];
   500        if (last_row && block_row == block_rows - 1)
   501          next_block_row = buffer_ptr;
   502        else
   503          next_block_row = buffer[block_row + 1] +
   504                           cinfo->master->first_MCU_col[ci];
   505        /* We fetch the surrounding DC values using a sliding-register approach.
   506         * Initialize all nine here so as to do the right thing on narrow pics.
   507         */
   508        DC1 = DC2 = DC3 = (int)prev_block_row[0][0];
   509        DC4 = DC5 = DC6 = (int)buffer_ptr[0][0];
   510        DC7 = DC8 = DC9 = (int)next_block_row[0][0];
   511        output_col = 0;
   512        last_block_column = compptr->width_in_blocks - 1;
   513        for (block_num = cinfo->master->first_MCU_col[ci];
   514             block_num <= cinfo->master->last_MCU_col[ci]; block_num++) {
   515          /* Fetch current DCT block into workspace so we can modify it. */
   516          jcopy_block_row(buffer_ptr, (JBLOCKROW)workspace, (JDIMENSION)1);
   517          /* Update DC values */
   518          if (block_num < last_block_column) {
   519            DC3 = (int)prev_block_row[1][0];
   520            DC6 = (int)buffer_ptr[1][0];
   521            DC9 = (int)next_block_row[1][0];
   522          }
   523          /* Compute coefficient estimates per K.8.
   524           * An estimate is applied only if coefficient is still zero,
   525           * and is not known to be fully accurate.
   526           */
   527          /* AC01 */
   528          if ((Al = coef_bits[1]) != 0 && workspace[1] == 0) {
   529            num = 36 * Q00 * (DC4 - DC6);
   530            if (num >= 0) {
   531              pred = (int)(((Q01 << 7) + num) / (Q01 << 8));
   532              if (Al > 0 && pred >= (1 << Al))
   533                pred = (1 << Al) - 1;
   534            } else {
   535              pred = (int)(((Q01 << 7) - num) / (Q01 << 8));
   536              if (Al > 0 && pred >= (1 << Al))
   537                pred = (1 << Al) - 1;
   538              pred = -pred;
   539            }
   540            workspace[1] = (JCOEF)pred;
   541          }
   542          /* AC10 */
   543          if ((Al = coef_bits[2]) != 0 && workspace[8] == 0) {
   544            num = 36 * Q00 * (DC2 - DC8);
   545            if (num >= 0) {
   546              pred = (int)(((Q10 << 7) + num) / (Q10 << 8));
   547              if (Al > 0 && pred >= (1 << Al))
   548                pred = (1 << Al) - 1;
   549            } else {
   550              pred = (int)(((Q10 << 7) - num) / (Q10 << 8));
   551              if (Al > 0 && pred >= (1 << Al))
   552                pred = (1 << Al) - 1;
   553              pred = -pred;
   554            }
   555            workspace[8] = (JCOEF)pred;
   556          }
   557          /* AC20 */
   558          if ((Al = coef_bits[3]) != 0 && workspace[16] == 0) {
   559            num = 9 * Q00 * (DC2 + DC8 - 2 * DC5);
   560            if (num >= 0) {
   561              pred = (int)(((Q20 << 7) + num) / (Q20 << 8));
   562              if (Al > 0 && pred >= (1 << Al))
   563                pred = (1 << Al) - 1;
   564            } else {
   565              pred = (int)(((Q20 << 7) - num) / (Q20 << 8));
   566              if (Al > 0 && pred >= (1 << Al))
   567                pred = (1 << Al) - 1;
   568              pred = -pred;
   569            }
   570            workspace[16] = (JCOEF)pred;
   571          }
   572          /* AC11 */
   573          if ((Al = coef_bits[4]) != 0 && workspace[9] == 0) {
   574            num = 5 * Q00 * (DC1 - DC3 - DC7 + DC9);
   575            if (num >= 0) {
   576              pred = (int)(((Q11 << 7) + num) / (Q11 << 8));
   577              if (Al > 0 && pred >= (1 << Al))
   578                pred = (1 << Al) - 1;
   579            } else {
   580              pred = (int)(((Q11 << 7) - num) / (Q11 << 8));
   581              if (Al > 0 && pred >= (1 << Al))
   582                pred = (1 << Al) - 1;
   583              pred = -pred;
   584            }
   585            workspace[9] = (JCOEF)pred;
   586          }
   587          /* AC02 */
   588          if ((Al = coef_bits[5]) != 0 && workspace[2] == 0) {
   589            num = 9 * Q00 * (DC4 + DC6 - 2 * DC5);
   590            if (num >= 0) {
   591              pred = (int)(((Q02 << 7) + num) / (Q02 << 8));
   592              if (Al > 0 && pred >= (1 << Al))
   593                pred = (1 << Al) - 1;
   594            } else {
   595              pred = (int)(((Q02 << 7) - num) / (Q02 << 8));
   596              if (Al > 0 && pred >= (1 << Al))
   597                pred = (1 << Al) - 1;
   598              pred = -pred;
   599            }
   600            workspace[2] = (JCOEF)pred;
   601          }
   602          /* OK, do the IDCT */
   603          (*inverse_DCT) (cinfo, compptr, (JCOEFPTR)workspace, output_ptr,
   604                          output_col);
   605          /* Advance for next column */
   606          DC1 = DC2;  DC2 = DC3;
   607          DC4 = DC5;  DC5 = DC6;
   608          DC7 = DC8;  DC8 = DC9;
   609          buffer_ptr++, prev_block_row++, next_block_row++;
   610          output_col += compptr->_DCT_scaled_size;
   611        }
   612        output_ptr += compptr->_DCT_scaled_size;
   613      }
   614    }
   615
   616    if (++(cinfo->output_iMCU_row) < cinfo->total_iMCU_rows)
   617      return JPEG_ROW_COMPLETED;
   618    return JPEG_SCAN_COMPLETED;
   619  }
   620
   500
   501    buffer = jsimd_huff_encode_one_block(state, buffer, block, last_dc_val,
   502                                         dctbl, actbl);
   503
   504    STORE_BUFFER()
   505
   506    return TRUE;
   507  }
