   509  LOCAL(boolean)
   510  encode_one_block(working_state *state, JCOEFPTR block, int last_dc_val,
   511                   c_derived_tbl *dctbl, c_derived_tbl *actbl)
   512  {
   513    int temp, temp2, temp3;
   514    int nbits;
   515    int r, code, size;
   516    JOCTET _buffer[BUFSIZE], *buffer;
   517    size_t put_buffer;  int put_bits;
   518    int code_0xf0 = actbl->ehufco[0xf0], size_0xf0 = actbl->ehufsi[0xf0];
   519    size_t bytes, bytestocopy;  int localbuf = 0;
   520
   521    put_buffer = state->cur.put_buffer;
   522    put_bits = state->cur.put_bits;
   523    LOAD_BUFFER()
   524
   525    /* Encode the DC coefficient difference per section F.1.2.1 */
   526
   527    temp = temp2 = block[0] - last_dc_val;
   528
   529    /* This is a well-known technique for obtaining the absolute value without a
   530     * branch.  It is derived from an assembly language technique presented in
   531     * "How to Optimize for the Pentium Processors", Copyright (c) 1996, 1997 by
   532     * Agner Fog.
   533     */
   534    temp3 = temp >> (CHAR_BIT * sizeof(int) - 1);
   535    temp ^= temp3;
   536    temp -= temp3;
   537
   538    /* For a negative input, want temp2 = bitwise complement of abs(input) */
   539    /* This code assumes we are on a two's complement machine */
   540    temp2 += temp3;
   541
   542    /* Find the number of bits needed for the magnitude of the coefficient */
   543    nbits = JPEG_NBITS(temp);
   544
   545    /* Emit the Huffman-coded symbol for the number of bits */
   546    code = dctbl->ehufco[nbits];
   547    size = dctbl->ehufsi[nbits];
   548    EMIT_BITS(code, size)
   549
   550    /* Mask off any extra bits in code */
   551    temp2 &= (((JLONG)1) << nbits) - 1;
   552
   553    /* Emit that number of bits of the value, if positive, */
   554    /* or the complement of its magnitude, if negative. */
   555    EMIT_BITS(temp2, nbits)
   556
   557    /* Encode the AC coefficients per section F.1.2.2 */
   558
   559    r = 0;                        /* r = run length of zeros */
   560
   561  /* Manually unroll the k loop to eliminate the counter variable.  This
   562   * improves performance greatly on systems with a limited number of
   563   * registers (such as x86.)
   564   */
   565  #define kloop(jpeg_natural_order_of_k) { \
   566    if ((temp = block[jpeg_natural_order_of_k]) == 0) { \
   567      r++; \
   568    } else { \
   569      temp2 = temp; \
   570      /* Branch-less absolute value, bitwise complement, etc., same as above */ \
   571      temp3 = temp >> (CHAR_BIT * sizeof(int) - 1); \
   572      temp ^= temp3; \
   573      temp -= temp3; \
   574      temp2 += temp3; \
   575      nbits = JPEG_NBITS_NONZERO(temp); \
   576      /* if run length > 15, must emit special run-length-16 codes (0xF0) */ \
   577      while (r > 15) { \
   578        EMIT_BITS(code_0xf0, size_0xf0) \
   579        r -= 16; \
   580      } \
   581      /* Emit Huffman symbol for run length / number of bits */ \
   582      temp3 = (r << 4) + nbits; \
   583      code = actbl->ehufco[temp3]; \
   584      size = actbl->ehufsi[temp3]; \
   585      EMIT_CODE(code, size) \
   586      r = 0; \
   587    } \
   588  }
   589
   590    /* One iteration for each value in jpeg_natural_order[] */
   591    kloop(1);   kloop(8);   kloop(16);  kloop(9);   kloop(2);   kloop(3);
   592    kloop(10);  kloop(17);  kloop(24);  kloop(32);  kloop(25);  kloop(18);
   593    kloop(11);  kloop(4);   kloop(5);   kloop(12);  kloop(19);  kloop(26);
   594    kloop(33);  kloop(40);  kloop(48);  kloop(41);  kloop(34);  kloop(27);
   595    kloop(20);  kloop(13);  kloop(6);   kloop(7);   kloop(14);  kloop(21);
   596    kloop(28);  kloop(35);  kloop(42);  kloop(49);  kloop(56);  kloop(57);
   597    kloop(50);  kloop(43);  kloop(36);  kloop(29);  kloop(22);  kloop(15);
   598    kloop(23);  kloop(30);  kloop(37);  kloop(44);  kloop(51);  kloop(58);
   599    kloop(59);  kloop(52);  kloop(45);  kloop(38);  kloop(31);  kloop(39);
   600    kloop(46);  kloop(53);  kloop(60);  kloop(61);  kloop(54);  kloop(47);
   601    kloop(55);  kloop(62);  kloop(63);
   602
   603    /* If the last coef(s) were zero, emit an end-of-block code */
   604    if (r > 0) {
   605      code = actbl->ehufco[0];
   606      size = actbl->ehufsi[0];
   607      EMIT_BITS(code, size)
   608    }
   609
   610    state->cur.put_buffer = put_buffer;
   611    state->cur.put_bits = put_bits;
   612    STORE_BUFFER()
   613
   614    return TRUE;
   615  }
