   618  /*
   619   * Emit a restart marker & resynchronize predictions.
   620   */
   621
   622  LOCAL(boolean)
   623  emit_restart(working_state *state, int restart_num)
   624  {
   625    int ci;
   626
   627    if (!flush_bits(state))
   628      return FALSE;
   629
   630    emit_byte(state, 0xFF, return FALSE);
   631    emit_byte(state, JPEG_RST0 + restart_num, return FALSE);
   632
   633    /* Re-initialize DC predictions to 0 */
   634    for (ci = 0; ci < state->cinfo->comps_in_scan; ci++)
   635      state->cur.last_dc_val[ci] = 0;
   636
   637    /* The restart counter is not updated until we successfully write the MCU. */
   638
   639    return TRUE;
   640  }
