   643  /*
   644   * Encode and output one MCU's worth of Huffman-compressed coefficients.
   645   */
   646
   647  METHODDEF(boolean)
   648  encode_mcu_huff(j_compress_ptr cinfo, JBLOCKROW *MCU_data)
   649  {
   650    huff_entropy_ptr entropy = (huff_entropy_ptr)cinfo->entropy;
   651    working_state state;
   652    int blkn, ci;
   653    jpeg_component_info *compptr;
   654
   655    /* Load up working state */
   656    state.next_output_byte = cinfo->dest->next_output_byte;
   657    state.free_in_buffer = cinfo->dest->free_in_buffer;
   658    ASSIGN_STATE(state.cur, entropy->saved);
   659    state.cinfo = cinfo;
   660
   661    /* Emit restart marker if needed */
   662    if (cinfo->restart_interval) {
   663      if (entropy->restarts_to_go == 0)
   664        if (!emit_restart(&state, entropy->next_restart_num))
   665          return FALSE;
   666    }
   667
   668    /* Encode the MCU data blocks */
   669    if (entropy->simd) {
   670      for (blkn = 0; blkn < cinfo->blocks_in_MCU; blkn++) {
   671        ci = cinfo->MCU_membership[blkn];
   672        compptr = cinfo->cur_comp_info[ci];
   673        if (!encode_one_block_simd(&state,
   674                                   MCU_data[blkn][0], state.cur.last_dc_val[ci],
   675                                   entropy->dc_derived_tbls[compptr->dc_tbl_no],
   676                                   entropy->ac_derived_tbls[compptr->ac_tbl_no]))
   677          return FALSE;
   678        /* Update last_dc_val */
   679        state.cur.last_dc_val[ci] = MCU_data[blkn][0][0];
   680      }
   681    } else {
   682      for (blkn = 0; blkn < cinfo->blocks_in_MCU; blkn++) {
   683        ci = cinfo->MCU_membership[blkn];
   684        compptr = cinfo->cur_comp_info[ci];
   685        if (!encode_one_block(&state,
   686                              MCU_data[blkn][0], state.cur.last_dc_val[ci],
   687                              entropy->dc_derived_tbls[compptr->dc_tbl_no],
   688                              entropy->ac_derived_tbls[compptr->ac_tbl_no]))
   689          return FALSE;
   690        /* Update last_dc_val */
   691        state.cur.last_dc_val[ci] = MCU_data[blkn][0][0];
   692      }
   693    }
   694
   695    /* Completed MCU, so update state */
   696    cinfo->dest->next_output_byte = state.next_output_byte;
   697    cinfo->dest->free_in_buffer = state.free_in_buffer;
   698    ASSIGN_STATE(entropy->saved, state.cur);
   699
   700    /* Update restart-interval state too */
   701    if (cinfo->restart_interval) {
   702      if (entropy->restarts_to_go == 0) {
   703        entropy->restarts_to_go = cinfo->restart_interval;
   704        entropy->next_restart_num++;
   705        entropy->next_restart_num &= 7;
   706      }
   707      entropy->restarts_to_go--;
   708    }
   709
   710    return TRUE;
